const API='https://prachi-nutrition-api.prachisayani-api.workers.dev';
async function api(path,options={}){const r=await fetch(API+path,{...options,credentials:'include',headers:{'Content-Type':'application/json',...(options.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.message||'Request failed ('+r.status+')');return d}
const cx=(...x)=>x.filter(Boolean).join(' ');
function Btn({children,kind='',...p}){return <button className={cx('btn',kind)} {...p}>{children}</button>}
function Notice({data}){return data?<div className={cx('notice',data.error&&'error')}>{data.error?<CircleHelp size={16}/>:<Check size={16}/>}<span>{data.text}</span></div>:null}
function Field({label,children}){return <label className="field"><span>{label}</span>{children}</label>}
function Badge({children,type=''}){return <span className={cx('badge',type)}>{children}</span>}
function Table({heads,rows,empty='Nothing here yet.'}){return <div className="table-wrap"><table><thead><tr>{heads.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.length?rows.map((r,i)=><tr key={r.id||i}>{r.cells.map((c,j)=><td key={j}>{c}</td>)}</tr>):<tr><td colSpan={heads.length} className="empty">{empty}</td></tr>}</tbody></table></div>}
function Auth({done}){const[mode,M]=useState('login'),[v,V]=useState({accountType:'client'}),[notice,N]=useState(null),[busy,B]=useState(false);const put=(k,x)=>V(p=>({...p,[k]:x}));async function submit(e){e.preventDefault();B(true);N(null);try{if(mode==='register'){if(v.password!==v.confirm)throw Error('Passwords do not match.');const d=await api('/auth/register',{method:'POST',body:JSON.stringify({full_name:v.name,email:v.email,mobile:v.mobile,password:v.password,account_type:v.accountType||'client'})});localStorage.setItem('pn-account-type:'+d.user.id,v.accountType);done({...d.user,is_platform_admin:false,memberships:[],account_type:d.user.account_type||v.accountType||'client',registration_intent:d.user.account_type||v.accountType||'client'})}else{await api('/auth/login',{method:'POST',body:JSON.stringify({identifier:v.identifier,password:v.password})});const d=await api('/auth/me');done({...d.user,registration_intent:d.user.account_type||localStorage.getItem('pn-account-type:'+d.user.id)||d.user.registration_intent||'client'})}}catch(e){N({text:e.message,error:true})}finally{B(false)}}
return <div className="auth"><aside className="auth-art"><div className="brand"><span className="brand-icon"><HeartPulse/></span>prachi<span>nutrition</span></div><div className="auth-copy"><Badge type="soft">PRACTICE WORKSPACE</Badge><h1>Better care starts with a more organised practice.</h1><p>One calm workspace for your nutrition team, verified professionals and client requests.</p><ul><li><ShieldCheck/> Secure account access</li><li><Users/> Connected care teams</li><li><Activity/> Practice operations in one place</li></ul></div><small className="art-foot">NUTRITION CARE · BUILT FOR CLINICAL WORKFLOWS</small></aside><section className="auth-side"><div className="auth-card"><div className="mobile-brand"><HeartPulse/> Prachi Nutrition</div><small className="eyebrow">WELCOME TO YOUR WORKSPACE</small><h2>{mode==='login'?'Sign in to your dashboard':'Create your account'}</h2><p className="muted">{mode==='login'?'Pick up where your practice left off.':'Set up your secure account to get started.'}</p><div className="tabs"><button className={mode==='login'?'active':''} onClick={()=>M('login')}>Sign in</button><button className={mode==='register'?'active':''} onClick={()=>M('register')}>Create account</button></div><form className="stack" onSubmit={submit}>{mode==='register'?<><Field label="Full name"><input required value={v.name||''} onChange={e=>put('name',e.target.value)} autoComplete="name" placeholder="Your full name"/></Field><Field label="Email address"><input required type="email" value={v.email||''} onChange={e=>put('email',e.target.value)} autoComplete="email" placeholder="you@example.com"/></Field><Field label="Mobile number (optional)"><input value={v.mobile||''} onChange={e=>put('mobile',e.target.value)} placeholder="+91"/></Field><Field label="Account type"><select value={v.accountType||'client'} onChange={e=>put('accountType',e.target.value)}><option value="client">Client — find a dietitian</option><option value="dietitian">Dietitian — apply for professional access</option></select></Field>{v.accountType==='dietitian'&&<p className="role-hint">Choosing Dietitian does not automatically verify your credentials or grant dashboard access. A practice administrator must invite or approve your account.</p>}</>:<Field label="Email or mobile number"><input required value={v.identifier||''} onChange={e=>put('identifier',e.target.value)} autoComplete="username" placeholder="Enter your email or mobile"/></Field>}<Field label="Password"><input required type="password" minLength="10" value={v.password||''} onChange={e=>put('password',e.target.value)} autoComplete={mode==='login'?'current-password':'new-password'} placeholder="At least 10 characters"/></Field>{mode==='register'&&<Field label="Confirm password"><input required type="password" minLength="10" value={v.confirm||''} onChange={e=>put('confirm',e.target.value)} placeholder="Re-enter password"/></Field>}<Notice data={notice}/><Btn disabled={busy}>{busy?'Please wait…':mode==='login'?'Sign in securely':'Create account'} <ArrowRight size={16}/></Btn></form><p className="auth-note"><ShieldCheck size={14}/> Protected by a secure HttpOnly session cookie.</p></div></section></div>}
