async function saveChart(publish=false){if(!activePatient||!carePracticeId){msg('Select a connected patient first.',true);return}try{const payload={practice_id:carePracticeId,client_user_id:activePatient,title:chartForm.title,notes:chartForm.notes,publish,plan:{energy_kcal:Number(chartForm.energy_kcal)||0,protein_g:Number(chartForm.protein_g)||0,carbohydrate_g:Number(chartForm.carbohydrate_g)||0,fat_g:Number(chartForm.fat_g)||0,meals:chartForm.meals}};const d=await api('/dietitian/plans',{method:'POST',body:JSON.stringify(payload)});msg(d.message||'Diet chart saved.');await loadPlans(activePatient)}catch(e){msg(e.message,true)}}
async function loadCareTools(){try{if(user?.account_type==='client'&&!dietitian){const ids=[...new Set(requests.filter(r=>r.client_user_id===user.id&&r.status==='accepted').map(r=>r.practice_id).filter(Boolean))];const [p,...care]=await Promise.all([api('/client/diet-plans'),...ids.flatMap(id=>[api('/dietitian/appointments?practice_id='+encodeURIComponent(id)),api('/dietitian/conversations?practice_id='+encodeURIComponent(id))])]);CPL(p.plans||[]);APT(care.filter((_,i)=>i%2===0).flatMap(x=>x.appointments||[]));const chats=care.filter((_,i)=>i%2===1).flatMap(x=>x.conversations||[]);CONV(chats);if(!activeConversation&&chats.length){ACONV(chats[0].id);await loadMessages(chats[0].id)}return}if(!carePracticeId)return;const [a,b]=await Promise.all([api('/dietitian/appointments?practice_id='+encodeURIComponent(carePracticeId)),api('/dietitian/conversations?practice_id='+encodeURIComponent(carePracticeId))]);APT(a.appointments||[]);CONV(b.conversations||[]);CPL([]);if(!activeConversation&&(b.conversations||[]).length){ACONV(b.conversations[0].id);await loadMessages(b.conversations[0].id)}}catch(e){msg(e.message,true)}}
function saveWeight(e){e.preventDefault();if(!user?.id)return;const weight=Number(weightForm.weight),height=Number(weightForm.height);if(!(weight>0&&weight<500&&height>0&&height<260)){msg('Enter a valid weight and height.',true);return}const entry={id:Date.now().toString(),date:weightForm.date||new Date().toISOString().slice(0,10),weight,height,bmi:Number((weight/((height/100)**2)).toFixed(1))};const next=[entry,...weightEntries].sort((a,b)=>new Date(b.date)-new Date(a.date));setWeightEntries(next);localStorage.setItem('pn-weight:'+user.id,JSON.stringify(next));setWeightForm(p=>({...p,weight:''}));msg('Weight and BMI entry saved on this device.')}function removeWeight(id){if(!user?.id)return;const next=weightEntries.filter(x=>x.id!==id);setWeightEntries(next);localStorage.setItem('pn-weight:'+user.id,JSON.stringify(next));}function addCareTask(e){e.preventDefault();if(!user?.id||!taskForm.title.trim())return;const next=[{id:Date.now().toString(),title:taskForm.title.trim(),due:taskForm.due,category:taskForm.category,completed:false,source:'Self-created',createdAt:new Date().toISOString()},...careTasks];setCareTasks(next);localStorage.setItem('pn-care-tasks:'+user.id,JSON.stringify(next));setTaskForm({title:'',due:'',category:'Self-care'});msg('Task added to your list.')}function toggleCareTask(id){if(!user?.id)return;const next=careTasks.map(t=>t.id===id?{...t,completed:!t.completed}:t);setCareTasks(next);localStorage.setItem('pn-care-tasks:'+user.id,JSON.stringify(next))}function removeCareTask(id){if(!user?.id)return;const next=careTasks.filter(t=>t.id!==id);setCareTasks(next);localStorage.setItem('pn-care-tasks:'+user.id,JSON.stringify(next))}
async function loadMessages(id){if(!id)return;try{const d=await api('/dietitian/messages?conversation_id='+encodeURIComponent(id));MS(d.messages||[])}catch(e){msg(e.message,true)}}
async function sendMessage(e){e.preventDefault();if(!activeConversation||!messageDraft.trim())return;try{await api('/dietitian/messages',{method:'POST',body:JSON.stringify({conversation_id:activeConversation,body:messageDraft})});MD('');await loadMessages(activeConversation)}catch(e){msg(e.message,true)}}
async function scheduleAppointment(e){e.preventDefault();if(!activePatient)return;const starts=e.currentTarget.starts_at.value,ends=e.currentTarget.ends_at.value;try{const d=await api('/dietitian/appointments',{method:'POST',body:JSON.stringify({practice_id:carePracticeId,client_user_id:activePatient,starts_at:new Date(starts).toISOString(),ends_at:new Date(ends).toISOString(),notes:e.currentTarget.notes.value})});msg(d.message||'Appointment scheduled.');e.currentTarget.reset();await loadCareTools()}catch(e){msg(e.message,true)}}
